with flagged as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval 45 minutes then 1 else 0 end as is_new_burst from device_readings), sessions_device_readings as (select *, sum(is_new_burst) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_id from flagged) select id, device_code, reading_ts, temp_c, pressure, status_bits, firmware, is_new_burst, session_id from sessions_device_readings order by reading_ts desc nulls first;
